# -*- coding: utf-8 -*-
r"""CUT Improvement Auto — install Night Drive + Light Drive + saved theme switch.

Put this file into <project>/scripts, then run from the project root:
  .\.venv\Scripts\python.exe .\scripts\install_cut_dual_themes.py

Supports both original app.css and earlier Night Drive installer. Re-runs are safe.
Touches ONLY frontend source files, creates external backups, does not build or
activate a release. No changes to backend, PostgreSQL, MAX, photos or backups.
"""
from __future__ import annotations
import base64
import hashlib
import os
from pathlib import Path
import re
import shutil
import sys
import tempfile
from datetime import datetime
import zlib

PAYLOADS = {
    'cut-night-drive.css': '',
    'cut-light-drive.css': '',
    'CutThemeControl.tsx': '',
    'improvement-auto-logo.png': '',
    'night-hero.jpg': '',
}

SHA256 = {
    'cut-night-drive.css': '323959b176108631dc0d71b42b63df9661b5014c648bc9926dbec5149444bc84',
    'cut-light-drive.css': 'e0c9e3baa495eeea2f9c28f2bd6e76918f68c623ca9fea9cbfa573798dd40a29',
    'CutThemeControl.tsx': '29837febe431fb07ea53adce3e9c02eea7660bd7a3d0d543ca87ddce002cf1bc',
    'improvement-auto-logo.png': '5cd04ae9ab8de71eb6f7cb17de8b19feebc4355619a1e935e43f54ecc9eb9075',
    'night-hero.jpg': '43c77bee82146418c6e713cafc37bba2fb429c7d8e42e610144cd04e165dee58',
}
OLD_NIGHT_SHA256 = '3ebfe408119396a94bc1f23772f0d0324847b30ef48f675585155a73f7464978'


DARK_IMPORT = 'import "./styles/cut-night-drive.css";'
LIGHT_IMPORT = 'import "./styles/cut-light-drive.css";'
THEME_IMPORT = 'import { CutThemeControl } from "./components/CutThemeControl";'


def digest(data: bytes) -> str:
    return hashlib.sha256(data).hexdigest()


def project_root() -> Path:
    script = Path(__file__).resolve()
    root = script.parent.parent
    required = [root/'frontend'/'src'/'App.tsx',
                root/'frontend'/'src'/'main.tsx',
                root/'frontend'/'src'/'styles'/'app.css',
                root/'frontend'/'public',
                root/'backend'/'app'/'main.py']
    if script.parent.name != 'scripts' or not all(p.exists() for p in required):
        raise RuntimeError('Put installer into project scripts/ folder. Expected React/Vite CUT project; nothing changed.')
    return root


def as_text(raw: bytes) -> tuple[str, bytes, str]:
    bom = b'\xef\xbb\xbf' if raw.startswith(b'\xef\xbb\xbf') else b''
    text = raw.decode('utf-8-sig')
    newline = '\r\n' if b'\r\n' in raw else '\n'
    return text, bom, newline


def pack_text(value: str, bom: bytes) -> bytes:
    return bom + value.encode('utf-8')


def css_import_pattern(name: str) -> re.Pattern[str]:
    return re.compile(r'''(?m)^[ \t]*import[ \t]+["']\./styles/''' + re.escape(name) + r'''["'];?[ \t]*(?=\r?$)''')


def update_app_tsx(raw: bytes) -> bytes:
    content, bom, newline = as_text(raw)
    base_import=css_import_pattern('app.css')
    night_import=css_import_pattern('cut-night-drive.css')
    light_import=css_import_pattern('cut-light-drive.css')
    if len(base_import.findall(content)) != 1:
        raise RuntimeError('App.tsx: need exactly one existing app.css import. Nothing changed.')
    if len(night_import.findall(content)) > 1 or len(light_import.findall(content)) > 1:
        raise RuntimeError('App.tsx: repeated theme CSS import. Nothing changed.')
    if not night_import.search(content):
        m=base_import.search(content)
        assert m is not None
        content=content[:m.end()] + newline + DARK_IMPORT + content[m.end():]
    if not light_import.search(content):
        m=night_import.search(content)
        assert m is not None
        content=content[:m.end()] + newline + LIGHT_IMPORT + content[m.end():]
    b=base_import.search(content)
    d=night_import.search(content)
    l=light_import.search(content)
    if not (b and d and l and b.start()<d.start()<l.start()):
        raise RuntimeError('App.tsx: theme CSS import order unexpected. Nothing changed.')
    return pack_text(content,bom)


def update_main_tsx(raw: bytes) -> bytes:
    content,bom,newline=as_text(raw)
    app_import=re.compile(r'''(?m)^[ \t]*import[ \t]+App[ \t]+from[ \t]+["'][^"']*App(?:\.tsx)?["'];?[ \t]*(?=\r?$)''')
    theme_import=re.compile(r'''(?m)^[ \t]*import[ \t]+\{[ \t]*CutThemeControl[ \t]*\}[ \t]+from[ \t]+["']\./components/CutThemeControl(?:\.tsx)?["'];?[ \t]*(?=\r?$)''')
    theme_jsx=re.compile(r'<CutThemeControl\s*/>')
    app_jsx=re.compile(r'<App\s*/>')
    if len(app_import.findall(content)) != 1 or len(app_jsx.findall(content)) != 1:
        raise RuntimeError('main.tsx: expected exactly one App import and <App />. Nothing changed.')
    if len(theme_import.findall(content)) > 1 or len(theme_jsx.findall(content)) > 1:
        raise RuntimeError('main.tsx: repeated theme control. Nothing changed.')
    if bool(theme_import.search(content)) != bool(theme_jsx.search(content)):
        raise RuntimeError('main.tsx: partial theme integration, refusing to guess. Nothing changed.')
    if not theme_import.search(content):
        m=app_import.search(content)
        assert m is not None
        content=content[:m.end()] + newline + THEME_IMPORT + content[m.end():]
        m=app_jsx.search(content)
        assert m is not None
        # A JSX fragment works both inside and without React.StrictMode.
        content=content[:m.start()] + '<><App /><CutThemeControl /></>' + content[m.end():]
    return pack_text(content,bom)


def atomic_write(path: Path, data: bytes) -> None:
    path.parent.mkdir(parents=True,exist_ok=True)
    fd,tmp=tempfile.mkstemp(prefix='.cut-themes-', suffix='.tmp',dir=path.parent)
    try:
        with os.fdopen(fd,'wb') as fp:
            fp.write(data)
            fp.flush()
            os.fsync(fp.fileno())
        os.replace(tmp,path)
    finally:
        if os.path.exists(tmp): os.unlink(tmp)


def main() -> int:
    print('=== CUT Improvement Auto / Dual theme installer ===')
    root=project_root()
    src=root/'frontend'/'src'
    app=src/'App.tsx'
    mainfile=src/'main.tsx'
    targets={
        src/'styles'/'cut-night-drive.css': 'cut-night-drive.css',
        src/'styles'/'cut-light-drive.css': 'cut-light-drive.css',
        src/'components'/'CutThemeControl.tsx': 'CutThemeControl.tsx',
        root/'frontend'/'public'/'cut-night-assets'/'improvement-auto-logo.png':'improvement-auto-logo.png',
        root/'frontend'/'public'/'cut-night-assets'/'night-hero.jpg':'night-hero.jpg',
    }
    decoded={}
    for dest,key in targets.items():
        buf=zlib.decompress(base64.b64decode(PAYLOADS[key]))
        if digest(buf)!=SHA256[key]:
            raise RuntimeError('Embedded payload damaged: '+key)
        decoded[dest]=buf

    # Validate the entire plan BEFORE writing anything.
    changes={}
    for dest,buf in decoded.items():
        if dest.exists():
            current=dest.read_bytes()
            if current==buf: continue
            if targets[dest]=='cut-night-drive.css' and digest(current)==OLD_NIGHT_SHA256:
                changes[dest]=buf  # upgrade only our exact old version, with backup
            else:
                raise RuntimeError('Not overwriting customized/unknown file: '+str(dest))
        else:
            changes[dest]=buf
    app_old=app.read_bytes()
    app_new=update_app_tsx(app_old)
    main_old=mainfile.read_bytes()
    main_new=update_main_tsx(main_old)
    if app_old!=app_new: changes[app]=app_new
    if main_old!=main_new: changes[mainfile]=main_new
    if not changes:
        print('OK: Both themes and persistent switch are already installed. No edits.')
        return 0

    stamp=datetime.now().strftime('%Y%m%d_%H%M%S_%f')
    backup=root.parent/'CUT_Improvement_Auto_DevArchive'/'dual_theme_backups'/stamp
    backup.mkdir(parents=True,exist_ok=False)
    originals={p:p.read_bytes() if p.exists() else None for p in changes}
    for p,old in originals.items():
        if old is not None:
            saved=backup/p.relative_to(root)
            saved.parent.mkdir(parents=True,exist_ok=True)
            shutil.copy2(p,saved)
    # All assets and code files first, App.tsx and main.tsx activation last.
    ordered=[p for p in changes if p not in (app,mainfile)]
    ordered += [p for p in (app,mainfile) if p in changes]
    applied=[]
    try:
        for p in ordered:
            atomic_write(p,changes[p])
            if digest(p.read_bytes())!=digest(changes[p]):
                raise RuntimeError('Written hash mismatch: '+str(p))
            applied.append(p)
    except Exception:
        for p in reversed(applied):
            old=originals[p]
            if old is None: p.unlink(missing_ok=True)
            else: atomic_write(p,old)
        print('ERROR: Changes rolled back; backup at '+str(backup),file=sys.stderr)
        raise
    print('OK: original Improvement Auto logo and car image installed.')
    print('OK: Night Drive and Light Drive styles installed.')
    print('OK: Accessible light/dark control installed in React root (login included).')
    print('OK: Theme choice persists locally after browser restart.')
    print('OK: Source app.css unchanged, files verified, rerunnable safely.')
    print('BACKUP: '+str(backup))
    print('CHANGED: '+', '.join(str(p.relative_to(root)) for p in ordered))
    print('UNCHANGED: active release 0.1.0, dist, backend, database, MAX, .env, photos, backups and Git.')
    print('NEXT: test source via Vite on http://127.0.0.1:5173; DO NOT build/activate yet.')
    return 0

if __name__ == '__main__':
    try:
        sys.exit(main())
    except Exception as exc:
        print('ERROR: '+str(exc),file=sys.stderr)
        sys.exit(1)
